import{_ as s,o as t,c as a,a2 as o}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"GitHub App","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/github-app.md","filePath":"deployment/github-app.md","lastUpdated":1792575534000}'),n={name:"deployment/github-app.md"};function l(r,e,p,c,i,d){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="github-app" tabindex="-1">GitHub App <a class="header-anchor" href="#github-app" aria-label="Permalink to &quot;GitHub App&quot;">​</a></h1><p><code>@chamvi/github</code> connects agents to a GitHub App: a verified webhook delivery becomes one deduplicated run per matching agent, and the GitHub tools act as the App&#39;s installation. API: <a href="/reference/github">@chamvi/github</a>.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/github</span><span style="color:#E7C58C;"> @chamvi/http</span><span style="color:#E7C58C;"> @chamvi/core</span><span style="color:#E7C58C;"> ai</span><span style="color:#E7C58C;"> --save</span></span></code></pre></div><h2 id="one-app-per-agent-repository" tabindex="-1">One App per agent repository <a class="header-anchor" href="#one-app-per-agent-repository" aria-label="Permalink to &quot;One App per agent repository&quot;">​</a></h2><p>Each agent repository (and so each image) gets its own GitHub App, with its own webhook URL, App credentials and Secret. There is no shared intake router: an App&#39;s webhooks go straight to the app that owns it.</p><ol><li>Create a GitHub App. Set the webhook URL to <code>https://&lt;host&gt;&lt;basePath&gt;/webhooks/github</code>, the <strong>content type to <code>application/json</code></strong> and a webhook secret. A hook created by hand defaults to <code>application/x-www-form-urlencoded</code>, which the route answers with <code>415</code>.</li><li>Grant the permissions the tools use (for triage: issues read and write, pull requests read, contents read, metadata read) and subscribe to the events the triggers name.</li><li>Generate a private key and install the App on the repositories the agents may act on.</li></ol><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> gh = createGithubApp({</span></span>
<span class="line"><span style="color:#E6DFDE;">    appId: process.env.GITHUB_APP_ID </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // a one-line PEM with literal \\n works</span></span>
<span class="line"><span style="color:#E6DFDE;">    privateKey: process.env.GITHUB_PRIVATE_KEY </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // [old, new] while rotating the secret</span></span>
<span class="line"><span style="color:#E6DFDE;">    webhookSecret: process.env.GITHUB_WEBHOOK_SECRET </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // the bot login without a GET /app</span></span>
<span class="line"><span style="color:#E6DFDE;">    slug: </span><span style="color:#E7C58C;">&#39;octo-triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // for runs not started by a delivery (the cron sweep below)</span></span>
<span class="line"><span style="color:#E6DFDE;">    installationId: </span><span style="color:#E7C58C;">12345678</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>The private key may be PKCS#1 or PKCS#8; literal <code>\\n</code> sequences become newlines, so a one-line env var works. Set <code>slug</code> in production: the self guard below then needs no <code>GET /app</code>.</p><h2 id="agents-and-the-webhook-route" tabindex="-1">Agents and the webhook route <a class="header-anchor" href="#agents-and-the-webhook-route" aria-label="Permalink to &quot;Agents and the webhook route&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> triage = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;triage&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Label new issues and ask for missing details in one comment.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    triggers: [</span></span>
<span class="line"><span style="color:#E6DFDE;">        githubWebhook({</span></span>
<span class="line"><span style="color:#E6DFDE;">            events: [</span><span style="color:#E7C58C;">&#39;issues.opened&#39;</span><span style="color:#E6DFDE;">],</span></span>
<span class="line"><span style="color:#958A8B;">            // skip issues opened by bots</span></span>
<span class="line"><span style="color:#E6DFDE;">            filter: (event) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> event.payload.sender?.type !== </span><span style="color:#E7C58C;">&#39;Bot&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        }),</span></span>
<span class="line"><span style="color:#958A8B;">        // a sweep for issues missed while the app was down</span></span>
<span class="line"><span style="color:#E6DFDE;">        cron(</span><span style="color:#E7C58C;">&#39;0 * * * *&#39;</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#E6DFDE;">    ],</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> ({ ...gh.readTools(), ...gh.writeTools() }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    approvals: { github_close_issue: </span><span style="color:#E7C58C;">&#39;user&#39;</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#958A8B;">    // delivery and cron runs have no invoker</span></span>
<span class="line"><span style="color:#E6DFDE;">    toolPolicy: requireToolPermission({ withoutInvoker: </span><span style="color:#E7C58C;">&#39;allow&#39;</span><span style="color:#E6DFDE;"> }),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [triage],</span></span>
<span class="line"><span style="color:#E6DFDE;">    resumeSecret: process.env.RESUME_SECRET </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> app = createHttpApp({</span></span>
<span class="line"><span style="color:#E6DFDE;">    engine,</span></span>
<span class="line"><span style="color:#E6DFDE;">    auth: staticTokens({</span></span>
<span class="line"><span style="color:#E6DFDE;">        tokens: [{</span></span>
<span class="line"><span style="color:#E6DFDE;">            value: process.env.CHAMVI_TOKEN </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            id: </span><span style="color:#E7C58C;">&#39;ci&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            permissions: [</span><span style="color:#E7C58C;">&#39;*&#39;</span><span style="color:#E6DFDE;">],</span></span>
<span class="line"><span style="color:#E6DFDE;">        }],</span></span>
<span class="line"><span style="color:#E6DFDE;">    }),</span></span>
<span class="line"><span style="color:#958A8B;">    // POST /webhooks/github; raise for large push or pull_request deliveries</span></span>
<span class="line"><span style="color:#E6DFDE;">    bodyLimit: </span><span style="color:#E7C58C;">4</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">1024</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">1024</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    routes: [gh.webhookRoute()],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p><code>githubWebhook({ events })</code> matches an event (<code>&#39;issues&#39;</code>, every action) or an event and action (<code>&#39;issues.opened&#39;</code>), then the optional <code>filter</code>. The run payload is a <code>GithubEvent { name, action?, delivery, installationId?, payload }</code> with the full GitHub body as <code>payload</code>.</p><p><code>POST /webhooks/github</code> comes through the <code>routes</code> option of <a href="/guide/http#extra-routes"><code>createHttpApp</code></a>:</p><ol><li>a missing <code>X-Hub-Signature-256</code> is <code>401</code>; a malformed <code>X-GitHub-Event</code> or <code>X-GitHub-Delivery</code> (1 to 255 characters) is <code>400</code>,</li><li>the body is read with the app&#39;s <code>bodyLimit</code> (<code>413</code> above it, <code>415</code> for a non-JSON content type),</li><li>the <code>sha256=</code> HMAC of the <strong>raw body bytes</strong> must match under one of the webhook secrets (constant time), else <code>401</code>; a body that is not a JSON object is <code>400</code>,</li><li>every agent with a matching trigger gets one run (its first matching trigger), with the delivery id (<code>X-GitHub-Delivery</code>) as the idempotency key unless the trigger&#39;s <code>idempotencyKey(event)</code> says otherwise, and by default <code>&lt;owner&gt;/&lt;repo&gt;#&lt;number&gt;</code> as the concurrency key,</li><li>events the App sent itself (<code>sender</code> is <code>&lt;slug&gt;[bot]</code> of <code>type: &#39;Bot&#39;</code>) start no run, so the agent does not trigger itself,</li><li>it answers <code>202 { delivery, runs: [{ agent, runId, deduplicated }] }</code> right away, also for <code>ping</code> and unmatched events; the runs happen asynchronously.</li></ol><p>The route is not rate limited and not behind the app&#39;s authenticators: the signature is its credential.</p><div class="warning custom-block"><p class="custom-block-title">The delivery id and the event name are not signed</p><p><code>X-Hub-Signature-256</code> covers the body only, not <code>X-GitHub-Delivery</code> or <code>X-GitHub-Event</code>. A captured signed delivery replayed under a new delivery id, or under another event name an agent listens on, starts new runs, each spending model tokens. On an exposed endpoint, give the trigger an <code>idempotencyKey</code> built from body fields only (the action, the repository, the issue and its <code>updated_at</code>, never <code>e.name</code> or <code>e.delivery</code>), and a <code>filter</code> that checks the body carries what the event name implies (<code>issue</code> for <code>issues</code>, <code>comment</code> for <code>issue_comment</code>).</p></div><div class="warning custom-block"><p class="custom-block-title">GitHub does not redeliver failed deliveries</p><p>A failing agent (a throwing <code>filter</code> or key function, a key above 255 characters, a failed dispatch) does not stop the others; each failure goes to <code>onError</code> and the answer is <code>500</code>. GitHub never retries a <code>4xx</code> or <code>5xx</code> delivery by itself: redeliver it by hand (the App&#39;s <em>Advanced</em> tab) or through the redelivery API. A redelivery keeps the delivery id, so the agents that already got their run are deduplicated.</p></div><p>Large <code>push</code> or <code>pull_request</code> deliveries can exceed the default <code>bodyLimit</code> of 1 MiB (GitHub sends up to 25 MB); raise <code>bodyLimit</code> on <code>createHttpApp</code> when an agent needs them. Two chamvi Apps on one repository see each other as ordinary bots: use a <code>filter</code> to break such loops.</p><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>Every tool acts as an installation: the delivery&#39;s for a run started by a delivery, else <code>installationId</code> from <code>createGithubApp()</code> (cron, REST and MCP runs); without either the run fails with <code>FatalToolError</code>. Installation tokens are cached per installation on the <code>clock</code> given to <code>createGithubApp()</code> (default <code>systemClock</code>, not the engine&#39;s), replaced five minutes before they expire (so a run resumed hours after an approval gets a fresh one) and never logged or stored. A failed GitHub call reaches the model as <code>GitHub &lt;status&gt;: &lt;message&gt;</code>, never with the request or its token. Every installation request carries the run&#39;s signal: cancel, drain and the run timeout abort a stalled call. The token exchange and <code>GET /app</code> are shared by every waiting run and delivery, so they are bounded by their own 30 s timeout on that same clock instead; a timed-out one is not cached and the next caller retries.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Kind</th><th>Purpose</th></tr></thead><tbody><tr><td><code>github_get_issue</code></td><td>read</td><td>One issue or pull request</td></tr><tr><td><code>github_search_issues</code></td><td>read</td><td>GitHub issue search, at most 20 results</td></tr><tr><td><code>github_list_labels</code></td><td>read</td><td>Every label of a repository</td></tr><tr><td><code>github_get_pull_request</code></td><td>read</td><td>One pull request with its branches</td></tr><tr><td><code>github_get_file</code></td><td>read</td><td>A file (cut at 65 536 characters) or a directory listing</td></tr><tr><td><code>github_get_latest_release</code></td><td>read</td><td>The latest release, or <code>{ none: true }</code></td></tr><tr><td><code>github_add_labels</code></td><td>effect</td><td>Adds labels (a set, so naturally idempotent)</td></tr><tr><td><code>github_create_comment</code></td><td>effect</td><td>One comment per issue per model step, found again by its marker</td></tr><tr><td><code>github_close_issue</code></td><td>effect</td><td>Closes an issue; meant to sit behind an <a href="/guide/approvals">approval</a></td></tr></tbody></table><p>Write tools are <a href="/guide/effect-tools">effect tools</a>. A comment embeds an <a href="/guide/effect-tools#the-crash-window"><code>effectMarker</code></a> keyed by run, issue and model step (<code>&lt;runId&gt;:github_create_comment:&lt;owner&gt;/&lt;repo&gt;#&lt;n&gt;:&lt;step&gt;</code>, owner and repo lower-cased since GitHub resolves them case-insensitively), and <code>alreadyApplied</code> looks for the App&#39;s own comment with that marker before posting. A crash between posting and recording redoes the model step with a different text, and the step-based key still finds the first comment, so nothing is posted twice. A second call for the same issue in the same step returns the first comment.</p><h2 id="security-notes" tabindex="-1">Security notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security notes&quot;">​</a></h2><ul><li>The tools reach every repository the installation reaches. Issue text is untrusted input: a model steered by it can act on any of them. Install the App only where the agent may act and put destructive tools behind approvals.</li><li><a href="/guide/tools#restricting-tools-per-invoker"><code>requireToolPermission()</code></a> denies every tool to runs without an invoker, which includes every delivery run. GitHub agents use <code>requireToolPermission({ withoutInvoker: &#39;allow&#39; })</code> or wrap it.</li><li>Sandboxes never get the App&#39;s credentials. A short-lived token scoped to one repository, for a sandbox that must push, is planned; the <a href="/guide/workspaces">workspaces</a> shipped without it.</li></ul>`,24)])])}const y=s(n,[["render",l]]);export{u as __pageData,y as default};
